          const gx = px + 24, gy = py + 27, gw = pw - 48, gh = 101;
          hint(px + 148, py + 4, 62, 14, "Change at 60 Hz", "How much the tape raises or lowers the bass at 60 Hz, in dB. Measured as output minus input.");
